use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

struct CancelHandle(AtomicBool);
impl CancelHandle {
    fn cancelled(&self) -> bool { self.0.load(Ordering::SeqCst) }
}

fn process(items: &[u64], cancel: &CancelHandle) -> u64 {
    let mut sum = 0;
    for &item in items {
        if cancel.cancelled() {
            break; // cooperative checkpoint
        }
        sum += item * item;
    }
    sum
}

fn main() {
    let cancel = CancelHandle(AtomicBool::new(false));
    println!("{}", process(&[1, 2, 3], &cancel));
    cancel.0.store(true, Ordering::SeqCst);
    println!("{}", process(&[1, 2, 3], &cancel)); // early exit → 0
}

