fn sum_until_limit(items: &[u64], cap: u64) -> u64 {
    let mut total = 0u64;
    for &item in items {
        let square = item * item;
        if total + square > cap {
            break;
        }
        total += square;
    }
    total
}

fn main() {
    println!("{}", sum_until_limit(&[1, 2, 3], 10));
    println!("{}", sum_until_limit(&[4, 9, 1], 100));
}
